package com.campusevents.model;
public class Student extends User {private final int studentId,year;private final String collegeId,department,phone;public Student(int uid,int sid,String name,String email,String hash,String college,String dept,int year,String phone){super(uid,name,email,hash);if(year<1||year>6||college==null||college.isBlank())throw new IllegalArgumentException("Invalid student details.");this.studentId=sid;this.collegeId=college;this.department=dept;this.year=year;this.phone=phone;}public int getStudentId(){return studentId;}public String getCollegeId(){return collegeId;}public String getDepartment(){return department;}public int getYear(){return year;}public String getPhone(){return phone;}public String getRole(){return "STUDENT";}}
